    },
    {
      "factor": "Professionalism and Risk Management",
      "polarity": -1,
      "reason_headline": "High-risk decisions and potential for reputational damage",
      "reason_detailed": "The agent's decision to act on insider information poses a significant risk to the company's reputation and potential for financial penalties. The agent's attempt to manage risk is compromised by its reliance on insider information and its lack of transparency."
    }
  ],
